toolScript:
// Game State
        let targetCMYK = { c: 0, m: 0, y: 0, k: 0 };
        let currentStreak = 0;
        let isRevealed = false;
        // --- Logic: CMYK to RGB Conversion (Approximate) ---
        function cmykToRgb(c, m, y, k) {
            // Inputs are 0-100, convert to 0-1
            const C = c / 100;
            const M = m / 100;
            const Y = y / 100;
            const K = k / 100;
            const r = 255 * (1 - C) * (1 - K);
            const g = 255 * (1 - M) * (1 - K);
            const b = 255 * (1 - Y) * (1 - K);
            return {
                r: Math.round(r),
                g: Math.round(g),
                b: Math.round(b)
            };
        }
        function rgbToHex(r, g, b) {
            return "#" + ((1 << 24) + (r << 16) + (g << 8) + b).toString(16).slice(1).toUpperCase();
        }
        // --- Game Functions ---
        function generateTarget() {
            // Generate random values. 
            // Bias slightly against 100% saturation on all channels to avoid pure blacks often
            targetCMYK = {
                c: Math.floor(Math.random() * 100),
                m: Math.floor(Math.random() * 100),
                y: Math.floor(Math.random() * 100),
                k: Math.floor(Math.random() * 60) // Limit Key to 60% max for more vibrant colors
            };
            const rgb = cmykToRgb(targetCMYK.c, targetCMYK.m, targetCMYK.y, targetCMYK.k);
            // Set Target Swatch
            const swatch = document.getElementById('target-swatch');
            swatch.style.backgroundColor = `rgb(${rgb.r}, ${rgb.g}, ${rgb.b})`;
            // Store hidden data for reveal
            swatch.dataset.rgb = `rgb(${rgb.r}, ${rgb.g}, ${rgb.b})`;
            swatch.dataset.hex = rgbToHex(rgb.r, rgb.g, rgb.b);
        }
        function updateMix() {
            if (isRevealed) return; // Lock inputs if revealed
            const c = parseInt(document.getElementById('slider-c').value);
            const m = parseInt(document.getElementById('slider-m').value);
            const y = parseInt(document.getElementById('slider-y').value);
            const k = parseInt(document.getElementById('slider-k').value);
            // Update Labels
            document.getElementById('val-c').innerText = c + "%";
            document.getElementById('val-m').innerText = m + "%";
            document.getElementById('val-y').innerText = y + "%";
            document.getElementById('val-k').innerText = k + "%";
            // Update User Swatch
            const rgb = cmykToRgb(c, m, y, k);
            document.getElementById('user-swatch').style.backgroundColor = `rgb(${rgb.r}, ${rgb.g}, ${rgb.b})`;
        }
        function submitGuess() {
            if (isRevealed) return;
            isRevealed = true;
            const userC = parseInt(document.getElementById('slider-c').value);
            const userM = parseInt(document.getElementById('slider-m').value);
            const userY = parseInt(document.getElementById('slider-y').value);
            const userK = parseInt(document.getElementById('slider-k').value);
            // Calculate Difference
            // We calculate Euclidean distance in 4D space and normalize it
            const diffC = Math.abs(targetCMYK.c - userC);
            const diffM = Math.abs(targetCMYK.m - userM);
            const diffY = Math.abs(targetCMYK.y - userY);
            const diffK = Math.abs(targetCMYK.k - userK);
            // Weighting: Key (K) has more visual impact on lightness
            const totalDiff = (diffC + diffM + diffY + (diffK * 1.5)) / 4.5;
            let accuracy = Math.max(0, 100 - totalDiff);
            // Boost scores slightly to make game feel fair (perceptual tolerance)
            accuracy = Math.min(100, accuracy * 1.1);
            const roundedScore = Math.floor(accuracy);
            // UI Updates
            const scoreEl = document.getElementById('result-score');
            scoreEl.innerText = roundedScore + "%";
            // Determine Feedback
            let message = "";
            if (roundedScore >= 95) {
                scoreEl.className = "text-5xl font-black text-green-500";
                message = "Perfection! You have a printer's eye.";
                currentStreak++;
            } else if (roundedScore >= 85) {
                scoreEl.className = "text-5xl font-black text-cyan-500";
                message = "Excellent mix! Very close match.";
                currentStreak++;
            } else if (roundedScore >= 70) {
                scoreEl.className = "text-5xl font-black text-yellow-500";
                message = "Good effort. Watch your contrast.";
                currentStreak = 0; // Reset streak on mediocre score
            } else {
                scoreEl.className = "text-5xl font-black text-red-500";
                message = "Way off. Try adjusting your Key (K).";
                currentStreak = 0;
            }
            document.getElementById('streak-display').innerText = currentStreak;
            // Show Feedback text
            const feedback = document.getElementById('feedback-text');
            feedback.innerText = message;
            feedback.classList.remove('opacity-0');
            // Reveal hidden data in Sidebar
            const swatch = document.getElementById('target-swatch');
            document.getElementById('target-hex').innerText = swatch.dataset.hex;
            document.getElementById('target-rgb-text').innerText = swatch.dataset.rgb;
            // Animate Overlay
            document.getElementById('user-swatch').classList.add('revealed');
            // Toggle Buttons
            document.getElementById('btn-submit').classList.add('hidden');
            document.getElementById('btn-next').classList.remove('hidden');
        }
        function nextRound() {
            isRevealed = false;
            // Reset UI
            document.getElementById('user-swatch').classList.remove('revealed');
            document.getElementById('btn-submit').classList.remove('hidden');
            document.getElementById('btn-next').classList.add('hidden');
            document.getElementById('feedback-text').classList.add('opacity-0');
            // Reset Sidebar Data
            document.getElementById('target-hex').innerText = "???";
            document.getElementById('target-rgb-text').innerText = "???";
            // Reset Sliders
            document.querySelectorAll('input[type=range]').forEach(input => input.value = 0);
            updateMix();
            // Generate New Color
            setTimeout(generateTarget, 300); // Slight delay for transition
        }
        document.addEventListener('DOMContentLoaded', () => {
            generateTarget();
            updateMix();
        });
